CREATE OR REPLACE FUNCTION public.bulk_update_products(p_token text, p_rows jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE r JSONB; n INT := 0; clash TEXT;
BEGIN
  IF NOT session_can(p_token, 'product_management') THEN
    RETURN json_build_object('success', false, 'error', 'You do not have permission to edit products');
  END IF;
  IF p_rows IS NULL OR jsonb_array_length(p_rows) = 0 THEN
    RETURN json_build_object('success', true, 'updated', 0);
  END IF;

  FOR r IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
    -- A barcode identifies exactly one product; refuse the whole save rather
    -- than leave two products fighting over the same scan.
    IF NULLIF(r->>'barcode', '') IS NOT NULL THEN
      SELECT name INTO clash FROM products
       WHERE barcode = r->>'barcode' AND id <> r->>'id' LIMIT 1;
      IF clash IS NOT NULL THEN
        RETURN json_build_object('success', false,
          'error', format('Barcode %s already belongs to "%s"', r->>'barcode', clash));
      END IF;
    END IF;

    UPDATE products SET
      cost_price = COALESCE((r->>'cost_price')::NUMERIC, cost_price),
      price      = COALESCE((r->>'price')::NUMERIC, price),
      barcode    = COALESCE(NULLIF(r->>'barcode', ''), barcode)
    WHERE id = r->>'id';
    IF FOUND THEN n := n + 1; END IF;
  END LOOP;

  RETURN json_build_object('success', true, 'updated', n);
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.close_drawer(p_token text, p_session_id text, p_counted numeric, p_note text DEFAULT ''::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE me RECORD; s RECORD; taken NUMERIC := 0; expected NUMERIC;
BEGIN
  IF NOT session_can(p_token, 'sales') THEN
    RETURN json_build_object('success', false, 'error', 'Not authorised');
  END IF;
  me := session_staff(p_token);

  SELECT * INTO s FROM drawer_sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN RETURN json_build_object('success', false, 'error', 'Drawer session not found'); END IF;
  IF s.closed_at IS NOT NULL THEN RETURN json_build_object('success', false, 'error', 'Drawer already closed'); END IF;

  SELECT COALESCE(SUM(
           CASE WHEN payment = 'Cash'  THEN total
                WHEN payment = 'Split' THEN split_cash
                ELSE 0 END), 0)
    INTO taken
    FROM sales
   WHERE NOT voided
     AND date >= s.opened_at
     AND (s.terminal = '' OR terminal = s.terminal);

  expected := COALESCE(s.opening_float, 0) + taken;

  UPDATE drawer_sessions SET
    closed_by = me.name, closed_at = now(),
    counted_cash = p_counted, expected_cash = expected,
    variance = p_counted - expected, note = p_note
  WHERE id = p_session_id;

  RETURN json_build_object('success', true, 'expected', expected,
    'counted', p_counted, 'variance', p_counted - expected, 'cashSales', taken);
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_wa_order(p_token text, p_order_id text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  me RECORD;
  v_order RECORD;
  v_item JSONB;
  v_prod RECORD;
  v_profit NUMERIC := 0;
  v_sale_id TEXT;
  v_receipt TEXT;
BEGIN
  IF NOT session_can(p_token, 'sales') THEN
    RETURN json_build_object('success', false, 'error', 'You do not have permission to process orders');
  END IF;
  me := session_staff(p_token);

  SELECT * INTO v_order FROM whatsapp_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RETURN json_build_object('success', false, 'error', 'Order not found'); END IF;
  IF v_order.status = 'Completed' THEN RETURN json_build_object('success', false, 'error', 'Already completed'); END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_order.items) LOOP
    IF NULLIF(v_item->>'productId', '') IS NOT NULL THEN
      SELECT * INTO v_prod FROM products WHERE id = v_item->>'productId';
    ELSE
      SELECT * INTO v_prod FROM products WHERE lower(name) = lower(v_item->>'name') LIMIT 1;
    END IF;
    IF FOUND THEN
      UPDATE products SET quantity = GREATEST(0, quantity - COALESCE((v_item->>'qty')::INTEGER, 0))
      WHERE id = v_prod.id;
      v_profit := v_profit + (
        COALESCE((v_item->>'price')::NUMERIC, 0) - v_prod.cost_price
      ) * COALESCE((v_item->>'qty')::INTEGER, 0);
    END IF;
  END LOOP;

  v_sale_id := short_id();
  v_receipt := generate_receipt_no();

  INSERT INTO sales (id, receipt_no, date, items, subtotal, discount, total, profit,
    payment, customer, type, cashier, voided)
  VALUES (v_sale_id, v_receipt, now(), v_order.items, v_order.subtotal, 0,
    v_order.total, v_profit, 'Paystack', v_order.customer_phone, 'WhatsApp',
    me.name, false);

  IF COALESCE(v_order.customer_phone, '') <> '' THEN
    INSERT INTO customers (phone, visit_count, total_spent, last_visit)
    VALUES (v_order.customer_phone, 1, v_order.total, now())
    ON CONFLICT (phone) DO UPDATE SET
      visit_count = customers.visit_count + 1,
      total_spent = customers.total_spent + v_order.total,
      last_visit = now();
  END IF;

  UPDATE whatsapp_orders SET
    status = 'Completed', processed_by = me.name, processed_at = now()
  WHERE id = p_order_id;

  RETURN json_build_object('success', true, 'receiptNo', v_receipt, 'saleId', v_sale_id);
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.deduct_order_stock(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_order   public.whatsapp_orders%rowtype;
  v_items   jsonb;
  v_item    jsonb;
  v_pid     uuid;
  v_qty     numeric;
  v_name    text;
begin
  select * into v_order from public.whatsapp_orders where id = p_order_id for update;
  if not found then
    return jsonb_build_object('success', false, 'error', 'order not found');
  end if;

  -- Already deducted -> do nothing (idempotent).
  if coalesce(v_order.stock_deducted, false) then
    return jsonb_build_object('success', true, 'note', 'already deducted');
  end if;

  -- items may be stored as jsonb or as a json string.
  begin
    if jsonb_typeof(v_order.items) is not null then
      v_items := v_order.items;
    else
      v_items := v_order.items::jsonb;
    end if;
  exception when others then
    v_items := (v_order.items #>> '{}')::jsonb;
  end;

  if v_items is null then
    update public.whatsapp_orders set stock_deducted = true where id = p_order_id;
    return jsonb_build_object('success', true, 'note', 'no items');
  end if;

  -- Loop items and decrement product stock. Match by product_id if present,
  -- else by name (website carts may store name only).
  for v_item in select * from jsonb_array_elements(v_items)
  loop
    v_qty  := coalesce((v_item->>'qty')::numeric, (v_item->>'quantity')::numeric, 1);
    v_pid  := null;
    begin v_pid := (v_item->>'productId')::uuid; exception when others then v_pid := null; end;
    v_name := coalesce(v_item->>'name', '');

    if v_pid is not null then
      update public.products
        set quantity = greatest(0, coalesce(quantity,0) - v_qty)
        where id = v_pid;
    elsif v_name <> '' then
      update public.products
        set quantity = greatest(0, coalesce(quantity,0) - v_qty)
        where lower(name) = lower(v_name);
    end if;
  end loop;

  update public.whatsapp_orders set stock_deducted = true where id = p_order_id;
  return jsonb_build_object('success', true, 'note', 'deducted');
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_staff(p_token text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE me staff; remaining INTEGER;
BEGIN
  IF NOT session_can(p_token, 'admin') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorised');
  END IF;
  me := session_staff(p_token);
  IF me.id = p_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'You cannot delete your own account');
  END IF;

  -- Never let the shop lock itself out of its own POS.
  SELECT COUNT(*) INTO remaining FROM staff
  WHERE active = true AND id <> p_id AND (role = 'Admin' OR COALESCE(permissions, '[]'::jsonb) ? 'admin');
  IF remaining = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'This is the last admin — deleting it would lock everyone out');
  END IF;

  DELETE FROM staff_sessions WHERE staff_id = p_id;
  DELETE FROM staff WHERE id = p_id;
  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_receipt_no()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE prefix TEXT; k TEXT; hi INTEGER;
BEGIN
  prefix := 'RCP' || to_char(now(), 'YYYYMMDD');
  k := 'receipt:' || prefix;
  SELECT COALESCE(MAX(substring(receipt_no from '(\d+)$')::INTEGER), 0) INTO hi
    FROM sales WHERE receipt_no LIKE prefix || '-%';
  PERFORM seed_counter(k, hi);
  RETURN prefix || '-' || lpad(next_counter(k)::text, 3, '0');
END;
$function$

