CREATE OR REPLACE FUNCTION public.process_refund(p_token text, p_receipt_no text, p_items jsonb, p_reason text, p_customer text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  me RECORD;
  v_sale RECORD;
  v_refund_id TEXT;
  v_refund_no TEXT;
  v_amount NUMERIC := 0;
  v_item JSONB;
  v_name TEXT;
  v_pid TEXT;
  v_qty INTEGER;
  v_sold INTEGER;
  v_already INTEGER;
  v_target TEXT;
  v_total_units INTEGER := 0;
  v_sold_units INTEGER := 0;
  v_is_full BOOLEAN := false;
BEGIN
  IF NOT session_can(p_token, 'refunds') THEN
    RETURN json_build_object('success', false, 'error', 'You do not have permission to process refunds');
  END IF;
  -- Who processed it comes from the session, not from the caller. The old
  -- signature took p_processed_by as a plain string, so a refund could be
  -- filed under somebody else's name.
  me := session_staff(p_token);

  SELECT * INTO v_sale FROM sales WHERE receipt_no = p_receipt_no FOR UPDATE;
  IF NOT FOUND THEN RETURN json_build_object('success', false, 'error', 'Sale not found'); END IF;
  IF v_sale.voided THEN RETURN json_build_object('success', false, 'error', 'Sale already voided'); END IF;
  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RETURN json_build_object('success', false, 'error', 'No items selected');
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_name := v_item->>'name';
    v_pid  := NULLIF(v_item->>'productId', '');
    v_qty  := GREATEST(COALESCE((v_item->>'qty')::INTEGER, 0), 0);
    IF v_qty = 0 THEN CONTINUE; END IF;

    SELECT COALESCE(SUM((s->>'qty')::INTEGER), 0) INTO v_sold
    FROM jsonb_array_elements(v_sale.items) s
    WHERE (v_pid IS NOT NULL AND s->>'productId' = v_pid)
       OR (v_pid IS NULL AND lower(s->>'name') = lower(v_name));

    SELECT COALESCE(SUM((r->>'qty')::INTEGER), 0) INTO v_already
    FROM refunds f, jsonb_array_elements(f.items) r
    WHERE f.original_receipt_no = p_receipt_no
      AND f.status = 'Completed'
      AND ((v_pid IS NOT NULL AND r->>'productId' = v_pid)
        OR (v_pid IS NULL AND lower(r->>'name') = lower(v_name)));

    IF v_qty > v_sold - v_already THEN
      RETURN json_build_object('success', false, 'error',
        format('%s: only %s left to refund on this receipt', v_name, GREATEST(v_sold - v_already, 0)));
    END IF;
  END LOOP;

  v_refund_id := short_id();
  v_refund_no := generate_refund_no();

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_name := v_item->>'name';
    v_pid  := NULLIF(v_item->>'productId', '');
    v_qty  := GREATEST(COALESCE((v_item->>'qty')::INTEGER, 0), 0);
    IF v_qty = 0 THEN CONTINUE; END IF;
    v_amount := v_amount + COALESCE((v_item->>'price')::NUMERIC, 0) * v_qty;

    IF v_pid IS NOT NULL THEN
      v_target := v_pid;
    ELSE
      SELECT id INTO v_target FROM products WHERE lower(name) = lower(v_name) LIMIT 1;
    END IF;
    IF v_target IS NOT NULL THEN
      UPDATE products SET quantity = quantity + v_qty WHERE id = v_target;
      INSERT INTO stock_ledger (product_id, product_name, previous_qty, change_qty, new_qty, reason, action_type, staff, reference)
      SELECT id, name, quantity - v_qty, v_qty, quantity, 'Refund ' || v_refund_no, 'return', me.name, p_receipt_no
      FROM products WHERE id = v_target;
    END IF;
  END LOOP;

  INSERT INTO refunds (id, refund_no, date, original_receipt_no, original_sale_id,
    items, refund_amount, reason, processed_by, customer, status)
  VALUES (v_refund_id, v_refund_no, now(), p_receipt_no, v_sale.id,
    p_items, v_amount, p_reason, me.name, p_customer, 'Completed');

  SELECT COALESCE(SUM((s->>'qty')::INTEGER), 0) INTO v_sold_units
  FROM jsonb_array_elements(v_sale.items) s;
  SELECT COALESCE(SUM((r->>'qty')::INTEGER), 0) INTO v_total_units
  FROM refunds f, jsonb_array_elements(f.items) r
  WHERE f.original_receipt_no = p_receipt_no AND f.status = 'Completed';

  IF v_total_units >= v_sold_units AND v_sold_units > 0 THEN
    UPDATE sales SET voided = true WHERE id = v_sale.id;
    v_is_full := true;
  END IF;

  RETURN json_build_object(
    'success', true, 'refundNo', v_refund_no,
    'refundAmount', v_amount, 'isFullRefund', v_is_full
  );
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.publish_release(p_token text, p_version text, p_path text, p_size bigint, p_notes text DEFAULT ''::text, p_platform text DEFAULT 'windows'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE me staff; new_id TEXT;
BEGIN
  IF NOT session_can(p_token, 'admin') THEN
    RETURN json_build_object('success', false, 'error', 'Only an admin can publish a build');
  END IF;
  me := session_staff(p_token);
  IF COALESCE(trim(p_version), '') = '' OR COALESCE(trim(p_path), '') = '' THEN
    RETURN json_build_object('success', false, 'error', 'A version and a file are both required');
  END IF;

  -- Only the newest build is offered; older rows stay for the record.
  UPDATE app_releases SET active = false WHERE platform = p_platform AND active;

  new_id := short_id();
  INSERT INTO app_releases (id, platform, version, object_path, size_bytes, notes, published_by)
  VALUES (new_id, p_platform, trim(p_version), trim(p_path), p_size, COALESCE(p_notes, ''), me.name);

  RETURN json_build_object('success', true, 'id', new_id, 'version', trim(p_version));
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.record_sale(p_items jsonb, p_customer text, p_payment text, p_discount numeric, p_type text, p_cashier text, p_split_cash numeric DEFAULT 0, p_split_momo numeric DEFAULT 0, p_terminal text DEFAULT ''::text, p_client_ref text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_id TEXT; v_receipt TEXT;
  v_subtotal NUMERIC := 0; v_profit NUMERIC := 0;
  v_total NUMERIC; v_discount NUMERIC;
  v_item JSONB; v_qty INTEGER; v_bundle_item JSONB;
  v_cost NUMERIC; v_have INTEGER;
  v_short JSONB := '[]'::jsonb;
  v_complete BOOLEAN := true;
  v_existing RECORD;
BEGIN
  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RETURN json_build_object('success', false, 'error', 'Cannot record an empty sale');
  END IF;

  IF p_client_ref IS NOT NULL AND p_client_ref <> '' THEN
    SELECT id, receipt_no, total, discount INTO v_existing
      FROM sales WHERE client_ref = p_client_ref LIMIT 1;
    IF FOUND THEN
      RETURN json_build_object('success', true, 'duplicate', true,
        'receiptNo', v_existing.receipt_no, 'saleId', v_existing.id,
        'total', v_existing.total, 'discount', v_existing.discount,
        'oversold', '[]'::jsonb, 'date', now());
    END IF;
  END IF;

  v_id := short_id();
  v_receipt := generate_receipt_no();

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_subtotal := v_subtotal + COALESCE((v_item->>'lineTotal')::NUMERIC, 0);
    v_qty := COALESCE((v_item->>'qty')::INTEGER, 0);
    v_cost := 0;
    IF (v_item->>'isBundle')::BOOLEAN IS TRUE AND v_item->'bundleItems' IS NOT NULL THEN
      SELECT COALESCE(SUM(p.cost_price * COALESCE((bi->>'qty')::INTEGER, 0)), 0) INTO v_cost
        FROM jsonb_array_elements(v_item->'bundleItems') bi
        JOIN products p ON p.id = bi->>'productId';
    ELSIF NULLIF(v_item->>'productId', '') IS NOT NULL THEN
      SELECT COALESCE(cost_price, 0) INTO v_cost FROM products WHERE id = v_item->>'productId';
      v_cost := COALESCE(v_cost, 0);
    END IF;
    -- A line with no cost makes the whole sale's profit an overstatement.
    IF v_cost <= 0 THEN v_complete := false; END IF;
    v_profit := v_profit + (COALESCE((v_item->>'price')::NUMERIC, 0) - v_cost) * v_qty;
  END LOOP;

  v_discount := LEAST(GREATEST(COALESCE(p_discount, 0), 0), v_subtotal);
  v_total := v_subtotal - v_discount;
  v_profit := v_profit - v_discount;

  BEGIN
    INSERT INTO sales (id, receipt_no, date, items, subtotal, discount, total, profit,
      payment, split_cash, split_momo, customer, type, cashier, voided, terminal,
      client_ref, profit_complete)
    VALUES (v_id, v_receipt, now(), p_items, v_subtotal, v_discount, v_total, v_profit,
      p_payment, COALESCE(p_split_cash, 0), COALESCE(p_split_momo, 0),
      p_customer, p_type, p_cashier, false, COALESCE(p_terminal, ''),
      NULLIF(p_client_ref, ''), v_complete);
  EXCEPTION WHEN unique_violation THEN
    SELECT id, receipt_no, total, discount INTO v_existing
      FROM sales WHERE client_ref = p_client_ref LIMIT 1;
    IF FOUND THEN
      RETURN json_build_object('success', true, 'duplicate', true,
        'receiptNo', v_existing.receipt_no, 'saleId', v_existing.id,
        'total', v_existing.total, 'discount', v_existing.discount,
        'oversold', '[]'::jsonb, 'date', now());
    END IF;
    RAISE;
  END;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    IF (v_item->>'isBundle')::BOOLEAN IS TRUE AND v_item->'bundleItems' IS NOT NULL THEN
      FOR v_bundle_item IN SELECT * FROM jsonb_array_elements(v_item->'bundleItems') LOOP
        v_qty := COALESCE((v_bundle_item->>'qty')::INTEGER, 0) * COALESCE((v_item->>'qty')::INTEGER, 1);
        UPDATE products SET quantity = GREATEST(0, quantity - v_qty)
        WHERE id = v_bundle_item->>'productId';
      END LOOP;
    ELSIF v_item->>'productId' IS NOT NULL THEN
      v_qty := COALESCE((v_item->>'qty')::INTEGER, 0);
      SELECT quantity INTO v_have FROM products WHERE id = v_item->>'productId' FOR UPDATE;
      IF FOUND AND v_have < v_qty THEN
        v_short := v_short || jsonb_build_object('name', v_item->>'name', 'wanted', v_qty, 'had', v_have);
      END IF;
      UPDATE products SET quantity = GREATEST(0, quantity - v_qty)
      WHERE id = v_item->>'productId';
    END IF;
  END LOOP;

  IF p_customer IS NOT NULL AND p_customer <> 'Walk-in' AND p_customer <> '' THEN
    INSERT INTO customers (phone, visit_count, total_spent, last_visit)
    VALUES (p_customer, 1, v_total, now())
    ON CONFLICT (phone) DO UPDATE SET
      visit_count = customers.visit_count + 1,
      total_spent = customers.total_spent + v_total,
      last_visit = now();
  END IF;

  RETURN json_build_object(
    'success', true, 'duplicate', false,
    'receiptNo', v_receipt, 'saleId', v_id,
    'subtotal', v_subtotal, 'discount', v_discount, 'total', v_total,
    'profitComplete', v_complete, 'oversold', v_short, 'date', now());
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.record_sale(p_items jsonb, p_customer text, p_payment text, p_discount numeric, p_type text, p_cashier text, p_split_cash numeric DEFAULT 0, p_split_momo numeric DEFAULT 0)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_id TEXT;
  v_receipt TEXT;
  v_subtotal NUMERIC := 0;
  v_profit NUMERIC := 0;
  v_total NUMERIC;
  v_discount NUMERIC;
  v_item JSONB;
  v_qty INTEGER;
  v_bundle_item JSONB;
  v_cost NUMERIC;
  v_have INTEGER;
  v_short JSONB := '[]'::jsonb;
BEGIN
  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RETURN json_build_object('success', false, 'error', 'Cannot record an empty sale');
  END IF;

  v_id := short_id();
  v_receipt := generate_receipt_no();

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_subtotal := v_subtotal + COALESCE((v_item->>'lineTotal')::NUMERIC, 0);
    v_qty := COALESCE((v_item->>'qty')::INTEGER, 0);
    v_cost := 0;

    IF (v_item->>'isBundle')::BOOLEAN IS TRUE AND v_item->'bundleItems' IS NOT NULL THEN
      -- A bundle costs the sum of what its components cost.
      SELECT COALESCE(SUM(p.cost_price * COALESCE((bi->>'qty')::INTEGER, 0)), 0)
        INTO v_cost
        FROM jsonb_array_elements(v_item->'bundleItems') bi
        JOIN products p ON p.id = bi->>'productId';
    ELSIF NULLIF(v_item->>'productId', '') IS NOT NULL THEN
      SELECT COALESCE(cost_price, 0) INTO v_cost FROM products WHERE id = v_item->>'productId';
      v_cost := COALESCE(v_cost, 0);
    END IF;

    v_profit := v_profit + (COALESCE((v_item->>'price')::NUMERIC, 0) - v_cost) * v_qty;
  END LOOP;

  v_discount := LEAST(GREATEST(COALESCE(p_discount, 0), 0), v_subtotal);
  v_total := v_subtotal - v_discount;
  v_profit := v_profit - v_discount;

  INSERT INTO sales (id, receipt_no, date, items, subtotal, discount, total, profit,
    payment, split_cash, split_momo, customer, type, cashier, voided)
  VALUES (v_id, v_receipt, now(), p_items, v_subtotal, v_discount, v_total, v_profit,
    p_payment, COALESCE(p_split_cash, 0), COALESCE(p_split_momo, 0),
    p_customer, p_type, p_cashier, false);

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    IF (v_item->>'isBundle')::BOOLEAN IS TRUE AND v_item->'bundleItems' IS NOT NULL THEN
      FOR v_bundle_item IN SELECT * FROM jsonb_array_elements(v_item->'bundleItems') LOOP
        v_qty := COALESCE((v_bundle_item->>'qty')::INTEGER, 0) * COALESCE((v_item->>'qty')::INTEGER, 1);
        UPDATE products SET quantity = GREATEST(0, quantity - v_qty)
        WHERE id = v_bundle_item->>'productId';
      END LOOP;
    ELSIF v_item->>'productId' IS NOT NULL THEN
      v_qty := COALESCE((v_item->>'qty')::INTEGER, 0);
      SELECT quantity INTO v_have FROM products WHERE id = v_item->>'productId' FOR UPDATE;
      IF FOUND AND v_have < v_qty THEN
        v_short := v_short || jsonb_build_object(
          'name', v_item->>'name', 'wanted', v_qty, 'had', v_have);
      END IF;
      UPDATE products SET quantity = GREATEST(0, quantity - v_qty)
      WHERE id = v_item->>'productId';
    END IF;
  END LOOP;

  IF p_customer IS NOT NULL AND p_customer <> 'Walk-in' AND p_customer <> '' THEN
    INSERT INTO customers (phone, visit_count, total_spent, last_visit)
    VALUES (p_customer, 1, v_total, now())
    ON CONFLICT (phone) DO UPDATE SET
      visit_count = customers.visit_count + 1,
      total_spent = customers.total_spent + v_total,
      last_visit = now();
  END IF;

  RETURN json_build_object(
    'success', true,
    'receiptNo', v_receipt,
    'saleId', v_id,
    'subtotal', v_subtotal,
    'discount', v_discount,
    'total', v_total,
    'oversold', v_short,
    'date', now()
  );
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_receiving(p_token text, p_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE me RECORD; rec RECORD;
BEGIN
  IF NOT session_can(p_token, 'admin') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only an admin can reject a delivery');
  END IF;
  me := session_staff(p_token);
  SELECT * INTO rec FROM receivings WHERE id = p_id FOR UPDATE;
  IF rec.id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not found'); END IF;
  IF rec.status <> 'pending' THEN RETURN jsonb_build_object('success', false, 'error', 'already ' || rec.status); END IF;

  UPDATE receivings SET status = 'rejected', reject_reason = COALESCE(p_reason, ''),
         approved_by = me.name, approved_at = now()
   WHERE id = p_id;
  RETURN jsonb_build_object('success', true);
END;
$function$

