CREATE OR REPLACE FUNCTION public.restore_order_stock(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_order public.whatsapp_orders%rowtype;
  v_items jsonb;
  v_item  jsonb;
  v_pid   uuid;
  v_qty   numeric;
  v_name  text;
begin
  select * into v_order from public.whatsapp_orders where id = p_order_id for update;
  if not found then
    return jsonb_build_object('success', false, 'error', 'order not found');
  end if;

  -- Only restore if it was actually deducted.
  if not coalesce(v_order.stock_deducted, false) then
    return jsonb_build_object('success', true, 'note', 'was not deducted');
  end if;

  begin
    if jsonb_typeof(v_order.items) is not null then v_items := v_order.items;
    else v_items := v_order.items::jsonb; end if;
  exception when others then v_items := (v_order.items #>> '{}')::jsonb; end;

  if v_items is not null then
    for v_item in select * from jsonb_array_elements(v_items)
    loop
      v_qty  := coalesce((v_item->>'qty')::numeric, (v_item->>'quantity')::numeric, 1);
      v_pid  := null;
      begin v_pid := (v_item->>'productId')::uuid; exception when others then v_pid := null; end;
      v_name := coalesce(v_item->>'name', '');
      if v_pid is not null then
        update public.products set quantity = coalesce(quantity,0) + v_qty where id = v_pid;
      elsif v_name <> '' then
        update public.products set quantity = coalesce(quantity,0) + v_qty where lower(name) = lower(v_name);
      end if;
    end loop;
  end if;

  update public.whatsapp_orders set stock_deducted = false where id = p_order_id;
  return jsonb_build_object('success', true, 'note', 'restored');
end;
$function$

CREATE OR REPLACE FUNCTION public.save_staff(p_token text, p_id text, p_name text, p_role text, p_pin text, p_active boolean, p_permissions jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE new_id TEXT; perms JSONB; clash INTEGER := 0; r RECORD;
BEGIN
  IF NOT session_can(p_token, 'admin') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorised');
  END IF;
  IF COALESCE(trim(p_name), '') = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Name is required');
  END IF;
  IF p_pin IS NOT NULL AND p_pin <> '' AND p_pin !~ '^\d{4,8}$' THEN
    RETURN jsonb_build_object('success', false, 'error', 'PIN must be 4-8 digits');
  END IF;

  IF p_pin IS NOT NULL AND p_pin <> '' THEN
    FOR r IN SELECT id, pin_hash FROM staff WHERE (p_id IS NULL OR p_id = '' OR id <> p_id) LOOP
      IF r.pin_hash IS NOT NULL AND r.pin_hash = crypt(p_pin, r.pin_hash) THEN clash := 1; EXIT; END IF;
    END LOOP;
    IF clash = 1 THEN
      RETURN jsonb_build_object('success', false, 'error', 'That PIN is already used by another staff member');
    END IF;
  END IF;

  perms := CASE WHEN p_role = 'Admin'
    THEN '["sales","refunds","stock_taking","product_receiving","product_management","inventory_view","reports","admin"]'::jsonb
    ELSE COALESCE(p_permissions, '[]'::jsonb) END;

  IF p_id IS NULL OR p_id = '' THEN
    IF p_pin IS NULL OR p_pin = '' THEN
      RETURN jsonb_build_object('success', false, 'error', 'A PIN is required for new staff');
    END IF;
    new_id := short_id();
    INSERT INTO staff (id, name, role, pin_hash, active, permissions)
    VALUES (new_id, trim(p_name), p_role, crypt(p_pin, gen_salt('bf', 10)), COALESCE(p_active, true), perms);
    RETURN jsonb_build_object('success', true, 'id', new_id);
  END IF;

  UPDATE staff SET
    name        = trim(p_name),
    role        = p_role,
    active      = COALESCE(p_active, true),
    permissions = perms,
    pin_hash    = CASE WHEN p_pin IS NULL OR p_pin = '' THEN pin_hash ELSE crypt(p_pin, gen_salt('bf', 10)) END
  WHERE id = p_id;

  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Staff not found'); END IF;
  RETURN jsonb_build_object('success', true, 'id', p_id);
END;
$function$

