CREATE OR REPLACE FUNCTION public.session_can(p_token text, p_perm text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE s staff; perms JSONB;
BEGIN
  s := session_staff(p_token);
  IF s.id IS NULL THEN RETURN false; END IF;
  IF s.role = 'Admin' THEN RETURN true; END IF;
  perms := COALESCE(s.permissions, '[]'::jsonb);
  RETURN perms ? 'admin' OR perms ? p_perm;
END;
$function$

CREATE OR REPLACE FUNCTION public.session_staff(p_token text)
 RETURNS staff
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE s staff;
BEGIN
  IF p_token IS NULL OR p_token = '' THEN RETURN NULL; END IF;
  SELECT st.* INTO s
  FROM staff_sessions ss
  JOIN staff st ON st.id = ss.staff_id
  WHERE ss.token = p_token
    AND ss.expires_at > now()
    AND st.active = true;
  IF FOUND THEN
    UPDATE staff_sessions SET last_seen = now() WHERE token = p_token;
  END IF;
  RETURN s;
END;
$function$

CREATE OR REPLACE FUNCTION public.sms_afternoon_report()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  td date := current_date;
  cnt int; rev numeric; prof numeric; cash numeric; momo numeric; exp numeric;
  msg text;
BEGIN
  SELECT count(*), coalesce(sum(total),0), coalesce(sum(profit),0),
    coalesce(sum(CASE WHEN payment='Cash' THEN total ELSE 0 END),0),
    coalesce(sum(CASE WHEN payment IN ('Momo','Paystack') THEN total ELSE 0 END),0)
  INTO cnt, rev, prof, cash, momo
  FROM sales WHERE date::date = td AND (voided=false OR voided IS NULL);

  SELECT coalesce(sum(amount),0) INTO exp FROM expenses WHERE date::date = td;

  msg := 'Afternoon Update' || chr(10) ||
    'Today So Far (' || to_char(td, 'Dy DD Mon') || ')' || chr(10) || chr(10) ||
    'Revenue: GHS ' || to_char(rev, 'FM999,999.00') || chr(10) ||
    'Sales: ' || cnt || chr(10) ||
    'Profit: GHS ' || to_char(prof, 'FM999,999.00') || chr(10) ||
    'Expenses: GHS ' || to_char(exp, 'FM999,999.00') || chr(10) ||
    'Net: GHS ' || to_char(prof - exp, 'FM999,999.00') || chr(10) || chr(10) ||
    'Cash: GHS ' || to_char(cash, 'FM999,999.00') || chr(10) ||
    'Momo: GHS ' || to_char(momo, 'FM999,999.00');

  IF cnt = 0 THEN
    msg := msg || chr(10) || chr(10) || 'No sales yet. Lets push!';
  END IF;

  msg := msg || chr(10) || '- Everytin Room';
  PERFORM send_admin_sms(msg);
END;
